('sql-ref-026', 'SELECT ROUND(salary, 2) AS rounded_salary FROM employees;'),
('sql-ref-027', 'SELECT * FROM employees WHERE salary > 50000;'),
('sql-ref-028', 'SELECT * FROM employees WHERE first_name LIKE ''A%'';'),
('sql-ref-029', 'SELECT * FROM employees ORDER BY department_id ASC, salary DESC;'),
('sql-ref-030', 'SELECT * FROM employees WHERE NOT (department_id = 2);'),
('sql-ref-031', 'SELECT department_id, COUNT(*) AS employee_count FROM employees GROUP BY department_id;'),
('sql-ref-032', 'SELECT department_id, MAX(salary) AS highest_salary FROM employees GROUP BY department_id;'),
('sql-ref-033', 'SELECT department_id, COUNT(*) AS employee_count FROM employees GROUP BY department_id HAVING COUNT(*) > 5;'),
('sql-ref-034', 'SELECT email, COUNT(*) AS occurrences FROM employees GROUP BY email HAVING COUNT(*) > 1;'),
('sql-ref-035', 'SELECT first_name, last_name, COUNT(*) AS occurrences FROM employees GROUP BY first_name, last_name HAVING COUNT(*) > 1;'),
('sql-ref-036', 'DELETE e FROM employees e JOIN (SELECT id FROM (SELECT id, ROW_NUMBER() OVER (PARTITION BY email ORDER BY id) AS rn FROM employees) ranked WHERE rn > 1) d ON d.id = e.id;'),
('sql-ref-037', 'SELECT * FROM employees WHERE manager_id IS NULL;'),
('sql-ref-038', 'SELECT * FROM employees WHERE hire_date >= CURRENT_DATE - INTERVAL 3 MONTH;'),
('sql-ref-039', 'SELECT * FROM employees ORDER BY id DESC LIMIT 3;'),
('sql-ref-040', 'SELECT * FROM (SELECT e.*, ROW_NUMBER() OVER (ORDER BY id) AS rn FROM employees e) ranked WHERE rn % 2 = 1;'),
('sql-ref-041', 'SELECT * FROM (SELECT e.*, ROW_NUMBER() OVER (ORDER BY id) AS rn FROM employees e) ranked WHERE rn % 2 = 0;'),
('sql-ref-042', 'SELECT DISTINCT salary FROM employees ORDER BY salary DESC LIMIT 1 OFFSET 1;'),
('sql-ref-043', 'SELECT DISTINCT salary FROM employees ORDER BY salary DESC LIMIT 1 OFFSET ?; -- Bind n - 1 as the offset.'),
('sql-ref-044', 'SELECT salary FROM employees ORDER BY salary DESC LIMIT 1;'),
('sql-ref-045', 'START TRANSACTION; SELECT first_name, last_name INTO @old_first, @old_last FROM employees WHERE id = 1 FOR UPDATE; UPDATE employees SET first_name = @old_last, last_name = @old_first WHERE id = 1; COMMIT;'),
('sql-ref-046', 'SELECT e.id, d.name FROM employees e INNER JOIN departments d ON d.id = e.department_id;'),
('sql-ref-047', 'SELECT e.id, d.name FROM employees e LEFT JOIN departments d ON d.id = e.department_id;'),
('sql-ref-048', 'SELECT e.id, d.name FROM employees e RIGHT JOIN departments d ON d.id = e.department_id;'),
('sql-ref-049', 'SELECT e.id, d.name FROM employees e LEFT JOIN departments d ON d.id = e.department_id UNION ALL SELECT e.id, d.name FROM employees e RIGHT JOIN departments d ON d.id = e.department_id WHERE e.id IS NULL;'),
('sql-ref-050', 'SELECT e.first_name AS employee, m.first_name AS manager FROM employees e LEFT JOIN employees m ON m.id = e.manager_id;'),
('sql-ref-051', 'SELECT DISTINCT c.id FROM current_employees c JOIN former_employees f ON f.id = c.id;'),
('sql-ref-052', 'SELECT email FROM customers UNION SELECT email FROM suppliers;'),
('sql-ref-053', 'SELECT email FROM customers UNION ALL SELECT email FROM suppliers;'),
('sql-ref-054', 'SELECT * FROM employees WHERE salary > (SELECT AVG(salary) FROM employees);'),
('sql-ref-055', 'SELECT department_id, COUNT(*) AS employees FROM employees GROUP BY department_id ORDER BY employees DESC, department_id LIMIT 1;'),
('sql-ref-056', 'CREATE TABLE employees_backup AS SELECT * FROM employees;'),
('sql-ref-057', 'CREATE TABLE employees_empty AS SELECT * FROM employees WHERE FALSE;'),
('sql-ref-058', 'INSERT INTO employees_backup SELECT * FROM employees WHERE department_id = 2;'),
('sql-ref-059', 'UPDATE employees SET salary = salary * 1.05 WHERE department_id = 2;'),
('sql-ref-060', 'DELETE FROM employees WHERE id = 42;'),
('sql-ref-061', 'SELECT * FROM employees WHERE LOWER(first_name) LIKE ''%an%'';'),
('sql-ref-062', 'SELECT * FROM employees WHERE LOWER(first_name) LIKE ''a%n'';'),
('sql-ref-063', 'SELECT id, salary, CASE WHEN salary >= 100000 THEN ''High'' WHEN salary >= 60000 THEN ''Mid'' ELSE ''Entry'' END AS salary_band FROM employees;'),
('sql-ref-064', 'SELECT * FROM employees WHERE hire_date >= ''2025-01-01'' AND hire_date < ''2026-01-01'';'),
('sql-ref-065', 'SELECT id, TIMESTAMPDIFF(YEAR, date_of_birth, CURRENT_DATE) AS age_years FROM employees;'),
('sql-ref-066', 'SELECT id, EXTRACT(DAY FROM hire_date) AS day, EXTRACT(MONTH FROM hire_date) AS month, EXTRACT(YEAR FROM hire_date) AS year FROM employees;'),
('sql-ref-067', 'SELECT * FROM orders WHERE ordered_at >= NOW() - INTERVAL 7 DAY;'),
('sql-ref-068', 'ALTER TABLE employees ADD COLUMN phone_number text;'),
('sql-ref-069', 'ALTER TABLE employees DROP COLUMN phone_number;'),
('sql-ref-070', 'ALTER TABLE employees RENAME COLUMN phone_number TO contact_number;'),
('sql-ref-071', 'SELECT id, salary, ROW_NUMBER() OVER (ORDER BY salary DESC, id) AS salary_position FROM employees;'),
('sql-ref-072', 'SELECT id, salary, RANK() OVER (ORDER BY salary DESC) AS salary_rank FROM employees;'),
('sql-ref-073', 'SELECT id, salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS salary_rank FROM employees;'),
('sql-ref-074', 'WITH ranked AS (SELECT e.*, DENSE_RANK() OVER (PARTITION BY department_id ORDER BY salary DESC) AS r FROM employees e) SELECT * FROM ranked WHERE r <= 3;'),
('sql-ref-075', 'SELECT id, department_id, salary, AVG(salary) OVER (PARTITION BY department_id) AS department_average FROM employees;'),
('sql-ref-076', 'SELECT id, hire_date, salary, SUM(salary) OVER (ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total FROM employees;'),
('sql-ref-077', 'SELECT id, salary, salary - LAG(salary) OVER (ORDER BY hire_date, id) AS change_from_previous FROM employees;'),
('sql-ref-078', 'SELECT id, salary, LEAD(salary) OVER (ORDER BY hire_date, id) AS next_salary FROM employees;'),
('sql-ref-079', 'SELECT e.id, e.salary, m.salary AS manager_salary FROM employees e JOIN employees m ON m.id = e.manager_id WHERE e.salary > m.salary;'),
('sql-ref-080', 'SELECT e1.id, e2.id, e1.salary FROM employees e1 JOIN employees e2 ON e1.salary = e2.salary AND e1.id < e2.id;'),
('sql-ref-081', 'WITH department_totals AS (SELECT department_id, COUNT(*) AS headcount FROM employees GROUP BY department_id) SELECT * FROM department_totals WHERE headcount > 5;'),
('sql-ref-082', 'WITH RECURSIVE tree AS (SELECT id, manager_id, first_name, 0 AS depth FROM employees WHERE manager_id IS NULL UNION ALL SELECT e.id, e.manager_id, e.first_name, t.depth + 1 FROM employees e JOIN tree t ON e.manager_id = t.id) SELECT * FROM tree ORDER BY depth, id;'),
('sql-ref-083', 'SELECT department_id, SUM(CASE WHEN salary < 60000 THEN 1 ELSE 0 END) AS below_60k, SUM(CASE WHEN salary >= 60000 THEN 1 ELSE 0 END) AS at_least_60k FROM employees GROUP BY department_id;'),
('sql-ref-084', 'SELECT id, ''first_name'' AS field, first_name AS value FROM employees UNION ALL SELECT id, ''last_name'', last_name FROM employees;'),
('sql-ref-085', 'SELECT * FROM employees WHERE salary > ALL (SELECT salary FROM employees WHERE department_id = 2);'),
('sql-ref-086', 'SELECT * FROM employees WHERE salary > ANY (SELECT salary FROM employees WHERE department_id = 2);'),
('sql-ref-087', 'SELECT d.id FROM departments d WHERE EXISTS (SELECT 1 FROM employees e WHERE e.department_id = d.id);'),
('sql-ref-088', 'SELECT d.id, d.name FROM departments d WHERE NOT EXISTS (SELECT 1 FROM employees e WHERE e.department_id = d.id);'),
('sql-ref-089', 'WITH ranked AS (SELECT salary, ROW_NUMBER() OVER (ORDER BY salary) AS rn, COUNT(*) OVER () AS total FROM employees) SELECT AVG(salary) AS median_salary FROM ranked WHERE rn IN (FLOOR((total + 1) / 2), FLOOR((total + 2) / 2));'),
('sql-ref-090', 'SELECT salary AS most_common_salary FROM employees GROUP BY salary ORDER BY COUNT(*) DESC, salary LIMIT 1;'),
('sql-ref-091', 'SELECT id, salary, ROUND(100.0 * SUM(salary) OVER (ORDER BY salary, id) / NULLIF(SUM(salary) OVER (), 0), 2) AS cumulative_percent FROM employees;'),
('sql-ref-092', 'SELECT id + 1 AS missing_from FROM (SELECT id, LEAD(id) OVER (ORDER BY id) AS next_id FROM employees) x WHERE next_id > id + 1;'),
('sql-ref-093', 'WITH RECURSIVE numbers AS (SELECT 1 AS sequence_number UNION ALL SELECT sequence_number + 1 FROM numbers WHERE sequence_number < 100) SELECT sequence_number FROM numbers;'),
('sql-ref-094', 'WITH days AS (SELECT DISTINCT user_id, DATE(login_at) AS day FROM logins), numbered AS (SELECT user_id, day, ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY day) AS rn FROM days), streaks AS (SELECT user_id, day, DATE_SUB(day, INTERVAL rn DAY) AS grp FROM numbered) SELECT user_id, MIN(day) AS first_day, MAX(day) AS last_day, COUNT(*) AS consecutive_days FROM streaks GROUP BY user_id, grp HAVING COUNT(*) >= 2;'),
('sql-ref-095', 'SELECT id, ordered_at, AVG(amount) OVER (ORDER BY ordered_at, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS moving_average FROM orders;'),
('sql-ref-096', 'WITH yearly AS (SELECT YEAR(ordered_at) AS year, SUM(amount) AS revenue FROM orders GROUP BY YEAR(ordered_at)) SELECT year, revenue, ROUND(100.0 * (revenue - LAG(revenue) OVER (ORDER BY year)) / NULLIF(LAG(revenue) OVER (ORDER BY year), 0), 2) AS yoy_growth_pct FROM yearly;'),
('sql-ref-097', 'SELECT * FROM articles WHERE MATCH(title, body) AGAINST (''+database +indexing'' IN BOOLEAN MODE); -- Requires a FULLTEXT index on (title, body).'),
('sql-ref-098', 'WITH days AS (SELECT DISTINCT user_id, DATE(login_at) AS day FROM logins), numbered AS (SELECT user_id, day, ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY day) AS rn FROM days), islands AS (SELECT user_id, day, DATE_SUB(day, INTERVAL rn DAY) AS island FROM numbered) SELECT user_id, COUNT(*) AS streak_days FROM islands GROUP BY user_id, island ORDER BY streak_days DESC;'),
('sql-ref-099', 'SELECT * FROM orders WHERE (ordered_at, id) < (?, ?) ORDER BY ordered_at DESC, id DESC LIMIT 25; -- Bind the cursor timestamp and ID.'),
('sql-ref-100', 'SELECT a.id, b.id FROM bookings a JOIN bookings b ON a.id < b.id AND a.starts_at < b.ends_at AND b.starts_at < a.ends_at;'),
('sql-ref-101', 'WITH ranked AS (SELECT e.*, ROW_NUMBER() OVER (PARTITION BY department_id ORDER BY salary DESC, id) AS rn FROM employees e) SELECT * FROM ranked WHERE rn = 1;'),
('sql-ref-102', 'WITH active AS (SELECT DISTINCT CAST(DATE_FORMAT(ordered_at, ''%Y-%m-01'') AS DATE) AS month, customer_id FROM orders), previous AS (SELECT month, COUNT(*) AS customers FROM active GROUP BY month) SELECT a.month, ROUND(100.0 * COUNT(p.customer_id) / NULLIF(MAX(pr.customers), 0), 2) AS retention_pct FROM active a LEFT JOIN active p ON p.customer_id = a.customer_id AND p.month = DATE_SUB(a.month, INTERVAL 1 MONTH) LEFT JOIN previous pr ON pr.month = DATE_SUB(a.month, INTERVAL 1 MONTH) GROUP BY a.month ORDER BY a.month;'),
('sql-ref-103', 'SELECT customer_id, GROUP_CONCAT(DISTINCT product_id ORDER BY product_id SEPARATOR '', '') AS products FROM orders GROUP BY customer_id;'),
('sql-ref-104', 'SELECT customer_id FROM orders WHERE product_id IN (101, 102) GROUP BY customer_id HAVING COUNT(DISTINCT product_id) = 2;'),
('sql-ref-105', 'SELECT id, salary, PERCENT_RANK() OVER (ORDER BY salary) AS percentile_rank FROM employees;'),
('sql-ref-106', 'WITH ordered AS (SELECT e.*, ROW_NUMBER() OVER (PARTITION BY department_id ORDER BY hire_date, id) AS first_rn, ROW_NUMBER() OVER (PARTITION BY department_id ORDER BY hire_date DESC, id DESC) AS last_rn FROM employees e) SELECT * FROM ordered WHERE first_rn = 1 OR last_rn = 1;'),
('sql-ref-107', 'SELECT e.id, d.id FROM employees e CROSS JOIN departments d;'),
('sql-ref-108', 'WITH ranked AS (SELECT e.*, ROW_NUMBER() OVER (PARTITION BY department_id ORDER BY hire_date ASC, id) AS rn FROM employees e) SELECT * FROM ranked WHERE rn = 1;'),
('sql-ref-109', 'SELECT department_id, MAX(salary) - MIN(salary) AS salary_range FROM employees GROUP BY department_id;'),
('sql-ref-110', 'SELECT manager_id, JSON_ARRAYAGG(id) AS direct_reports FROM employees WHERE manager_id IS NOT NULL GROUP BY manager_id;')
